from collections import deque
seen=set(); comps=[]
for r in range(5):
 for c in range(12):
  if g[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
